/**
 * ADR 1048 — the adopter pack manifest at RUNTIME: `packs/.adopter-manifest.json`.
 *
 * An adopter (a white-label downstream: KickTodo, Book AI, …) attests its own
 * packs in this file, generated by `scripts/gen-steward-manifest.mjs --adopter`
 * and committed in the ADOPTER's repo — upstream never tracks one
 * (`scripts/build-whitelabel-zip.sh` refuses to). It carries three things, all
 * bound to one content digest per pack:
 *
 *   trust  → `host/packTrust.ts` classifies a keyed pack whose bytes match as the
 *            `adopter` tier, AFTER the steward check (so no first-party verdict
 *            can change);
 *   floor  → `adopterServedTypeIds()` is an arm of `isSideEffectingNode`, and
 *            `adopterDeclaredTypeIds()` tells the runtime manifest floor
 *            (`packs/tarballLoader.ts`) which typeIds a build already decided;
 *   mount  → `adopterClaimedPackDirs()` is a mount claim for
 *            `bootstrap/mountLocalPacks.ts`, whatever the directory's prefix.
 *
 * ── WHERE IT IS READ FROM, AND WHY NOTHING CAN MOVE THAT ───────────────────
 *
 * The SAME directory `packTrust.ts` reads the steward manifest from: located by
 * walking up from THIS MODULE's own path to `packs/.steward-manifest.json`, never
 * from `OPENWOP_LOCAL_PACKS_DIR` or any other env var (ADR 0555: no env var may
 * redefine which attestation is believed). The adopter file is then read from
 * that directory by its fixed name — never searched for on its own, so a stray
 * `.adopter-manifest.json` higher up the filesystem cannot be found instead.
 *
 * ── ANY VIOLATION REJECTS THE WHOLE FILE ───────────────────────────────────
 *
 * Validated once, at first read, then frozen. The rules (`validateAdopterManifest`)
 * are a twin of `scripts/lib/adopter-pack-manifest.mjs`, pinned equal by
 * `test/adr1048-adopter-manifest-parity.test.ts` — the generator runs before the
 * build and the image carries no `scripts/lib/`, the `pack-content-digest` case.
 * Rejected ⇒ every claimed pack classifies `untrusted/adopter_manifest_rejected`
 * and does not dispatch, so none of its nodes can reach a replay unclassified.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { locateRepoDir } from './_repoPath.js';
import { ADOPTER_PACK_PINS } from '../features/adopterPackPins.generated.js';
import { MANIFEST_DECLARED_TYPE_IDS } from '../executor/sideEffectFloor.generated.js';
import { createLogger } from '../observability/logger.js';

const log = createLogger('host.adopterPackManifest');

export const ADOPTER_MANIFEST_FILE = '.adopter-manifest.json';
const STEWARD_MANIFEST_FILE = '.steward-manifest.json';

// ── the rules (twin of scripts/lib/adopter-pack-manifest.mjs) ───────────────

export const RESERVED_PREFIXES: readonly string[] = Object.freeze(['core.openwop.', 'community.openwop.']);
export const UPSTREAM_VENDOR_PREFIXES: readonly string[] = Object.freeze(['vendor.openwop-app.', 'vendor.openwop.', 'vendor.myndhyve.']);
/** ADR 1048 D7 — explicit ids, never a prefix. KickTodo's packs predate the
 *  `vendor.<adopter>.*` rule and replay pins key on these names (ADR 1031 inv. 1). */
export const GRANDFATHERED_ADOPTER_PACK_IDS: readonly string[] = Object.freeze(['feature.kicktodo.nodes', 'vendor.openwop-app.kicktodo.agents']);
export const ADOPTER_NAMESPACE = /^vendor\.[a-z0-9][a-z0-9-]*\.[a-z0-9][a-z0-9.-]*$/;
export const REPLAY_CLASSES: readonly string[] = Object.freeze(['served', 'ai-invocation-log', 'pure']);

export interface AdopterManifestEntry {
  version: string | null;
  files: number;
  digest: string;
  declared: string[];
  served: string[];
  held: Record<string, string[]>;
  servedUnresolved?: string[];
  replayClass?: Record<string, string>;
}
export interface AdopterManifest {
  version: 1;
  packs: Record<string, AdopterManifestEntry>;
}
export interface AdopterManifestViolation { code: string; detail: string }
export interface AdopterValidationContext {
  stewardKeys: ReadonlySet<string>;
  pins: Readonly<Record<string, string>> | null;
  upstreamDeclared: ReadonlySet<string>;
  packNameOf: (dir: string) => string | null;
}

const isStringArray = (v: unknown): v is string[] => Array.isArray(v) && v.every((x) => typeof x === 'string');
const isPlainObject = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v);

function isEntry(e: unknown): e is AdopterManifestEntry {
  if (!isPlainObject(e)) return false;
  return typeof e.digest === 'string' && typeof e.files === 'number'
    && (typeof e.version === 'string' || e.version === null)
    && isStringArray(e.declared) && isStringArray(e.served)
    && isPlainObject(e.held) && Object.values(e.held).every(isStringArray)
    && (e.servedUnresolved === undefined || isStringArray(e.servedUnresolved))
    && (e.replayClass === undefined || isPlainObject(e.replayClass));
}

/** `[]` ⇒ valid. Codes match the generator twin's for the same input. */
export function validateAdopterManifest(m: unknown, ctx: AdopterValidationContext): AdopterManifestViolation[] {
  const v: AdopterManifestViolation[] = [];
  const add = (code: string, detail: string): void => { v.push({ code, detail }); };
  if (!isPlainObject(m) || m.version !== 1 || !isPlainObject(m.packs)) {
    add('shape', 'expected { version: 1, packs: { … } }');
    return v;
  }
  const packs = m.packs;
  const pins = ctx.pins ?? {};
  for (const [key, e] of Object.entries(packs)) {
    if (!isEntry(e)) {
      add('shape', `${key}: entry is not { version, files, digest, declared[], served[], held{}, servedUnresolved[]?, replayClass{}? }`);
      continue;
    }
    if (ctx.stewardKeys.has(key)) add('shadows_steward', `${key} is a steward-manifest key`);
    if (RESERVED_PREFIXES.some((p) => key.startsWith(p))) add('reserved_prefix', `${key} uses a protocol namespace`);
    else if (!GRANDFATHERED_ADOPTER_PACK_IDS.includes(key)
      && (!ADOPTER_NAMESPACE.test(key) || UPSTREAM_VENDOR_PREFIXES.some((p) => key.startsWith(p)))) {
      add('namespace', `${key} is not vendor.<adopter>.* (and is not a grandfathered id)`);
    }
    const name = ctx.packNameOf(key);
    if (name !== key) add('name_dir_mismatch', `packs/${key}/pack.json name is ${name === null ? '(unreadable)' : `'${name}'`}`);
    if (!Object.hasOwn(pins, key)) add('pin_missing', `${key} has no ADOPTER_PACK_PINS entry`);
    else if (pins[key] !== e.version) add('pin_version', `${key}: manifest ${e.version} ≠ pin ${pins[key]}`);
    const declared = new Set(e.declared);
    for (const t of e.declared) {
      if (ctx.upstreamDeclared.has(t)) add('typeid_upstream', `${key}: ${t} is an upstream typeId`);
      if (!t.startsWith(`${key}.`)) add('typeid_namespace', `${key}: ${t} is outside the pack's own namespace`);
    }
    for (const t of [...e.served, ...Object.values(e.held).flat(), ...(e.servedUnresolved ?? [])]) {
      if (!declared.has(t)) add('floor_not_declared', `${key}: ${t} is in the floor half but not declared`);
    }
    for (const [t, cls] of Object.entries(e.replayClass ?? {})) {
      if (t.includes('*') || !declared.has(t)) add('replay_class', `${key}: replayClass names '${t}', which is not one of this pack's own declared typeIds`);
      if (!REPLAY_CLASSES.includes(cls)) add('replay_class', `${key}: ${t} declares '${cls}' (allowed: ${REPLAY_CLASSES.join(', ')})`);
    }
  }
  for (const key of Object.keys(pins)) {
    if (!Object.hasOwn(packs, key)) add('pin_unattested', `ADOPTER_PACK_PINS pins ${key}, which the manifest does not attest`);
  }
  return v;
}

// ── the frozen state ─────────────────────────────────────────────────────────

export type AdopterManifestState =
  | { readonly status: 'absent'; readonly source: string | null }
  | {
    readonly status: 'valid';
    readonly source: string;
    readonly manifest: AdopterManifest;
    readonly served: ReadonlySet<string>;
    readonly declared: ReadonlySet<string>;
  }
  | {
    readonly status: 'rejected';
    readonly source: string;
    readonly claimed: ReadonlySet<string>;
    readonly violations: readonly AdopterManifestViolation[];
  };

interface TestOverride {
  manifest: unknown;
  /** Where `<key>/pack.json` is read for the name = directory rule. */
  packsDir: string;
  pins: Readonly<Record<string, string>>;
  stewardKeys?: ReadonlySet<string>;
}

let cache: AdopterManifestState | undefined;
let override: TestOverride | undefined;

/** The code-anchored `packs/` directory (where the steward manifest lives), or null. */
function anchoredPacksDir(): string | null {
  try {
    return locateRepoDir(dirname(fileURLToPath(import.meta.url)), 'packs', STEWARD_MANIFEST_FILE);
  } catch {
    return null;
  }
}

function readStewardKeys(packsDir: string): ReadonlySet<string> {
  try {
    const parsed = JSON.parse(readFileSync(join(packsDir, STEWARD_MANIFEST_FILE), 'utf-8')) as { packs?: Record<string, unknown> };
    return new Set(Object.keys(parsed.packs ?? {}));
  } catch {
    return new Set();
  }
}

function packNameReader(packsDir: string): (dir: string) => string | null {
  return (dir) => {
    try {
      const parsed = JSON.parse(readFileSync(join(packsDir, dir, 'pack.json'), 'utf-8')) as { name?: unknown };
      return typeof parsed.name === 'string' ? parsed.name : null;
    } catch {
      return null;
    }
  };
}

function freeze(source: string, raw: unknown, ctx: AdopterValidationContext): AdopterManifestState {
  const violations = validateAdopterManifest(raw, ctx);
  if (violations.length > 0) {
    const claimed = new Set(isPlainObject(raw) && isPlainObject(raw.packs) ? Object.keys(raw.packs) : []);
    log.error('adopter pack manifest REJECTED — no adopter pack will dispatch (ADR 1048 D3: any violation rejects the whole file). '
      + 'Regenerate with `node scripts/gen-steward-manifest.mjs --adopter`.', { source, violations });
    return { status: 'rejected', source, claimed, violations: Object.freeze([...violations]) };
  }
  const manifest = raw as AdopterManifest;
  const served = new Set<string>();
  const declared = new Set<string>();
  for (const e of Object.values(manifest.packs)) {
    for (const t of e.served) served.add(t);
    for (const t of e.declared) declared.add(t);
  }
  return { status: 'valid', source, manifest, served, declared };
}

function load(): AdopterManifestState {
  if (override) {
    return freeze(join(override.packsDir, ADOPTER_MANIFEST_FILE), override.manifest, {
      stewardKeys: override.stewardKeys ?? (() => { const d = anchoredPacksDir(); return d ? readStewardKeys(d) : new Set<string>(); })(),
      pins: override.pins,
      upstreamDeclared: MANIFEST_DECLARED_TYPE_IDS,
      packNameOf: packNameReader(override.packsDir),
    });
  }
  const packsDir = anchoredPacksDir();
  if (packsDir === null) return { status: 'absent', source: null };
  const source = join(packsDir, ADOPTER_MANIFEST_FILE);
  // Absent is the upstream case and every adopter without packs: no adopter tier.
  if (!existsSync(source)) return { status: 'absent', source };
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(source, 'utf-8'));
  } catch {
    raw = null; // unparseable ⇒ `shape` ⇒ rejected, never "absent"
  }
  return freeze(source, raw, {
    stewardKeys: readStewardKeys(packsDir),
    pins: ADOPTER_PACK_PINS,
    upstreamDeclared: MANIFEST_DECLARED_TYPE_IDS,
    packNameOf: packNameReader(packsDir),
  });
}

/** The adopter manifest as loaded, validated and frozen at first read. */
export function adopterManifestState(): AdopterManifestState {
  if (cache === undefined) cache = load();
  return cache;
}

const EMPTY: ReadonlySet<string> = new Set();

/** Adopter typeIds its build SERVES on a replay fork — an `isSideEffectingNode` arm. */
export function adopterServedTypeIds(): ReadonlySet<string> {
  const s = adopterManifestState();
  return s.status === 'valid' ? s.served : EMPTY;
}

/** Adopter typeIds its build CLASSIFIED (served or held) — the runtime manifest
 *  floor leaves these alone, exactly as it leaves upstream's alone. */
export function adopterDeclaredTypeIds(): ReadonlySet<string> {
  const s = adopterManifestState();
  return s.status === 'valid' ? s.declared : EMPTY;
}

/** Pack directories the adopter manifest claims — a mount claim. A REJECTED
 *  manifest still claims its directories: they mount, classify untrusted, and
 *  refuse with the real reason instead of silently vanishing. */
export function adopterClaimedPackDirs(): ReadonlySet<string> {
  const s = adopterManifestState();
  if (s.status === 'valid') return new Set(Object.keys(s.manifest.packs));
  if (s.status === 'rejected') return s.claimed;
  return EMPTY;
}

/** Test-only: drop the frozen state. */
export function __resetAdopterManifestForTests(): void {
  cache = undefined;
}

/** Test-only: validate and freeze `input` in place of the code-anchored file
 *  (null restores the real path). Same rules, same freeze. */
export function __setAdopterManifestForTests(input: TestOverride | null): void {
  override = input ?? undefined;
  cache = undefined;
}
